import express from 'express';
import mongoose from 'mongoose';
import cors from 'cors';
import bodyParser from 'body-parser';
import cookieParser from 'cookie-parser';
import dotenv from 'dotenv';
dotenv.config();

import { connectDB } from './config/dbConnect.js';
import posts from './routes/api/posts.js';
import users from './routes/auth/register.js';
import login from './routes/auth/login.js';

const app = express();
const PORT = 7070 || process.env.PORT;

// const users = [];

//connect database
connectDB();

app.use(cors());
app.use(cookieParser());
app.use(express.urlencoded({ extended: false }));
app.use(express.json());
app.use(bodyParser.json());
app.use(bodyParser.urlencoded({ extended: false }));

app.use('/api/v1', posts);
app.use('/api/v1', users);
app.use('/api/v1', login);

mongoose.connection.once('open', ()=> {
  console.log("Connected to MongoDB! 🚀🚀🚀🚀")
  app.listen(PORT, () => console.log(`Server running on port ${PORT} ⚡⚡⚡⚡`))
})
export default app

import mongoose from "mongoose";

export const connectDB = async () => {
  try {
    await mongoose.connect(process.env.DATABASE_URI,{
      useUnifiedTopology: true,
      useNewUrlParser: true
    })
  } catch (error) {
    console.error(error)
  }
}

import express from 'express';
import {
  createNewPost,
  deletePost,
  getAllPosts,
  getPost,
  updatePost,
} from '../../controllers/postsController.js';
import { verifyUserToken } from '../../middlewares/verifyUsertoken.js';

const router = express.Router();

router.route('/post').get(getAllPosts);
router.route('/post/:id').get(getPost);

router.route('/post').post(verifyUserToken, createNewPost);
router.route('/post/:id').delete(verifyUserToken, deletePost);
router.route('/post/:id').put(verifyUserToken, updatePost);

export default router;

import Post from '../models/Post.js';
import { postValidate } from '../validation/postValidSchema.js';

export const getAllPosts = async (req, res) => {
  try {
    const posts = await Post.find();
    res
      .status(200)
      .json({ status: 'success', message: 'all posts', data: posts });
  } catch (e) {
    console.log(e);
    res.status(500).json({ status: 'success', message: 'internal server error' });
  }
};
export const createNewPost = async (req, res) => {
  try {
    const { title, subTitle, postBody, imageUrl } = req.body;
    const { error } = postValidate({ title, subTitle, postBody, imageUrl });

    if (error) {
      return res.status(400).json({ status: 'fail', message: error.details[0].message });
    }

    const result = await Post.create({
      title: title,
      subTitle: subTitle,
      postBody: postBody,
      imageUrl: imageUrl,
    });
    res
      .status(201)
      .json({
        status: 'success',
        message: 'post created',
        data: result
      });
  } catch (error) {
    console.error(error);
    res.status(500).json({ status: 'fail', error: 'internal server error' });
  }
};
export const getPost = async (req, res) => {
  try {
    const { id } = req.params;
    const post = await Post.findOne({ _id: id });

    if (!post)
      return res
        .status(404)
        .json({ status: 'fail', message: 'post not found' });

    res
      .status(200)
      .json({ status: 'success', message: 'post found', data: post });
  } catch (e) {
    console.log(e);
    res.status(404).json({ status: 'fail', error: `post ${id} not found` });
  }
};
export const updatePost = async (req, res) => {
  try {
    const { id } = req.params;

    const { title, subTitle, postBody, imageUrl } = req.body;
    const { error } = postValidate({ title, subTitle, postBody, imageUrl });

    if (error) {
      return res.status(400).json({ status: 'fail', message: 'Enter valid data' });
    }
    const post = await Post.findOne({ _id: id });

    post.title = title;
    post.subTitle = subTitle;
    post.postBody = postBody;
    post.imageUrl = imageUrl;

    const result = await post.save();
    res
      .status(200)
      .json({ status: 'success', message: 'post updated', data: result });
  } catch (e) {
    console.log(e);
    res.status(400).json({ status: 'fail', message: `post not found` });
  }
};

export const deletePost = async (req, res) => {
  try {
    const { id } = req.params;
    const post = await Post.findByIdAndDelete({ _id: id });

    if (!post)
      return res
        .status(404)
        .json({ status: 'fail', message: 'post not found' });
    res.status(204).json({ status: 'success', message: 'post deleted' });
  } catch (e) {
    console.log(e);
    res.status(400).json({ status: 'fail', error: `post not found` });
  }
};

import Joi from 'joi';

export const postValidate = (data) => {
  const schema = Joi.object().keys({
    title: Joi.string().min(5).required(),
    subTitle: Joi.string().min(5).required(),
    postBody: Joi.string().min(20).required(),
    imageUrl: Joi.string().min(10).required(),
  });

  const value = schema.validate(data, { abortEarly: false });
  return value;
};

import jwt from 'jsonwebtoken'
import dotenv from 'dotenv'
dotenv.config()

export const verifyUserToken = (req, res, next) => {
    if(!req.headers.authorization){
        return res.status(401).json({"status": "fail", "message": "Unauthorized request!"})
    }

    const token = req.headers['authorization'].split(" ")[1]
    if(!token){
        return res.status(401).json({"status": "fail", "message":"Access denied. No token provided."})
    }
    try {
        const decoded = jwt.verify(token, process.env.ACCESS_SECRET_TOKEN);
        req.user = decoded.userInfo.email
        req.roles = decoded.userInfo.roles

        next()
    } catch (error) {
        res.status(400).json({"status": "fail", "message":"Invalid token."})
    }
}

