import User from '../models/User';
import bcrypt from 'bcryptjs';

export const createUser = async (req, res) => {
  try {
    const { firstname, lastname, email, password } = req.body;

    if (!firstname || !lastname || !email || !password) {
      res.status(400).json({ status: 'fail', message: 'required fields' });
    }

    const userFind = await User.findOne({ email: email }).exec();
    if (userFind)
      return res
        .status(409)
        .json({ status: 'fail', message: 'User already exists' });

    const hashedPwd = await bcrypt.hash(password, 10);

    const result = await User.create({
      email: email,
      password: hashedPwd,
      firstname: firstname,
      lastname: lastname,
    });

    res.status(201).json({
      status: 'success',
      message: 'user created',
      data: { User: `${email} created` },
    });
  } catch (error) {
    res.status(500).json({ status: 'fail', error: error.message });
  }
};

export const updateUser = async (req, res) => {
  try {
    const { firstname, lastname, email, password } = req.body;

    if (!req.user)
      return res
        .status(400)
        .json({ status: 'fail', message: 'no logged in user' });
    const user = await User.findOne({ email: email });

    if (!user)
      return res
        .status(404)
        .json({ status: 'fail', message: 'no user match found' });

    if (!firstname || !lastname || !email || !password) {
      res.status(400).json({ status: 'fail', message: 'required fields' });
    }
    const hashedPwd = await bcrypt.hash(password, 10);

    if (req.user) user.email = req.user;
    if (password) user.password = hashedPwd;
    if (firstname) user.firstname = firstname;
    if (lastname) user.lastname = lastname;

    const result = await user.save();

    res
      .status(200)
      .json({ status: 'success', message: 'user updated', data: result });

    res
      .status(201)
      .json({ status: 'success', data: { User: `${email} created` } });
  } catch (error) {
    res.status(500).json({ status: 'fail', error: error.message });
  }
};

import mongoose from "mongoose";

const userSchema = new mongoose.Schema({
    email: {
        type: String,
        required: true
    },
    roles: {
        User: {
         type: Number, 
         default: 1
        },
        Admin: {
         type: Number, 
         default: 0
        }
    },
    password: {
     type: String, 
     required: true
    },
    firstname: {
     type: String, 
     required: true
    },
    lastname: {
     type: String, 
     required: true
    },
    refreshToken: String,
    dateCreated: { type: Date, default: Date.now },
})

export default mongoose.model('User', userSchema)

import User from '../models/User';
import jwt from 'jsonwebtoken';
import bcrypt from 'bcryptjs';

export const login = async (req, res) => {
  try {
    const { email, password } = req.body;

    if (!email || !password) {
      res
        .status(500)
        .json({ status: 'fail', message: 'email and password are required' });
    }

    const userFound = await User.findOne({ email: email });

    if (!userFound)
      return res
        .status(404)
        .json({ status: 'fail', message: 'user not found' });

    const ispassWordValid = await bcrypt.compare(password, userFound.password);

    if (!ispassWordValid)
      return res
        .status(400)
        .json({ status: 'fail', error: 'Invalid email or password' });

    const roles = Object.values(userFound.roles);

    const accessToken = jwt.sign(
      {
        userInfo: {
          id: userFound._id,
          email: userFound.email,
          roles: roles,
        },
      },
      process.env.ACCESS_SECRET_TOKEN,
      { expiresIn: '1h' }
    );
    const refreshToken = jwt.sign(
      {
        email: userFound.email,
      },
      process.env.REFRESH_SECRET_TOKEN,
      { expiresIn: '1d' }
    );

    userFound.refreshToken = refreshToken;
    await userFound.save();

    res.cookie('authToken', refreshToken, {
      httpOnly: true,
      maxAge: 24 * 60 * 60 * 1000,
    });
    res.status(200).json({
      status: 'success',
      message: 'logged in successfully',
      data: { accessToken: accessToken },
    });
  } catch (error) {
    res.status(401).json({ status: 'fail', error: 'invalid credentials' });
  }
};

